assignments.value:
={{ 
  const required = ['client_name', 'content_type', 'topic', 'target_audience'];
  const errors = required.filter(field => !$json[field] || $json[field].toString().trim() === '');
  const supportedTypes = ['blog_post', 'social_media', 'email_newsletter', 'product_description', 'landing_page', 'press_release', 'case_study', 'whitepaper'];

  if ($json.content_type && !supportedTypes.includes($json.content_type)) {
    errors.push('content_type');
  }

  return {
    valid: errors.length === 0,
    errors: errors,
    sanitized: {
      client_name: $json.client_name?.toString().trim(),
      content_type: $json.content_type?.toString().trim(),
      topic: $json.topic?.toString().trim(),
      target_audience: $json.target_audience?.toString().trim(),
      keywords: $json.keywords ? $json.keywords.split(',').map(k => k.trim()) : [],
      brand_voice: $json.brand_voice?.toString().trim() || 'professional',
      desired_length: parseInt($json.desired_length) || 1000,
      purpose: $json.purpose?.toString().trim() || 'educational',
      call_to_action: $json.call_to_action?.toString().trim() || '',
      additional_notes: $json.additional_notes?.toString().trim() || '',
      seo_focus: $json.seo_focus === 'true' || $json.seo_focus === true,
      include_images: $json.include_images === 'true' || $json.include_images === true,
      created_at: new Date().toISOString(),
      request_id: $workflow.id + '-' + $runIndex + '-' + Date.now()
    }
  };
}}

